class FlagClient {
  constructor(fetchFn) {
    this.fetchFn = fetchFn;
    this.cache = null;
    this.ts = 0;
  }
  async isEnabled(flag) {
    const now = Date.now();
    if (this.cache !== null && now - this.ts < 60000) return this.cache;
    const val = await this.fetchFn(flag);
    this.cache = val;
    this.ts = now;
    return val;
  }
}
```

